-- Focused NEW recovery cases only. Root runs locally after applying the CLI patch.
begin;
do $$
declare own uuid;other_actor uuid;br uuid:=gen_random_uuid();other_br uuid:=gen_random_uuid();closed_req uuid:=gen_random_uuid();created_req uuid:=gen_random_uuid();r jsonb;again jsonb;created jsonb;consent jsonb;denied boolean;profile_count bigint;receipt_count bigint;audit_count bigint;
 phone text:='+201'||lpad((abs(hashtextextended(gen_random_uuid()::text,0))%1000000000)::text,9,'0');
 car jsonb:=jsonb_build_object('plate_number','QA-FENCE-'||left(gen_random_uuid()::text,8),'brand','QA','model','Close fence');
begin
 select user_id into strict own from public.staff_profiles where role='owner' and is_active limit 1;
 select user_id into strict other_actor from public.staff_profiles where role='manager' and is_active limit 1;
 insert into public.business_branches(branch_id,name_ar,name_en) values(br,'اختبار إغلاق تسجيل','Registration fence QA'),(other_br,'فرع آخر','Other fence QA');
 insert into public.staff_branch_access(user_id,branch_id) values(other_actor,br),(other_actor,other_br);
 consent:=jsonb_build_object('accepted',true,'version','offline-registration-v1','text',private.offline_registration_notice('en'),'language','en');
 assert not has_table_privilege('authenticated','private.offline_registration_closed_requests','SELECT');
 assert not has_table_privilege('service_role','private.offline_registration_closed_requests','INSERT');
 assert not has_function_privilege('anon','public.close_offline_customer_registration(uuid,uuid)','EXECUTE');
 assert not has_function_privilege('service_role','private.close_offline_customer_registration(uuid,uuid)','EXECUTE');
 select count(*) into profile_count from private.offline_customer_profiles;
 select count(*) into receipt_count from private.offline_customer_enrollment_receipts;
 execute 'set local role authenticated';perform set_config('request.jwt.claim.sub',own::text,true);
 r:=public.get_offline_customer_registration(closed_req);assert r->>'status'='absent' and r->>'definitive_failure'='false';
 r:=public.close_offline_customer_registration(closed_req,br);assert r->>'state'='closed' and r->>'definitive_failure'='true' and r->>'may_retry_same_request'='false' and r->'enrollment_secret'='null'::jsonb;
 again:=public.close_offline_customer_registration(closed_req,br);assert again=r,'Lost close response must replay the same permanent result';
 again:=public.get_offline_customer_registration(closed_req);assert again->>'status'='closed' and again->>'branch_id'=br::text and again->>'may_retry_same_request'='false';
 denied:=false;begin perform public.register_offline_customer(closed_req,br,'QA fence customer',phone,'EG',car,consent);exception when sqlstate '55000' then denied:=true;end;assert denied,'Late creator reopened a closed UUID';
 denied:=false;begin perform public.close_offline_customer_registration(closed_req,other_br);exception when insufficient_privilege then denied:=true;end;assert denied,'Close ignored bound branch';
 denied:=false;begin perform public.register_offline_customer(closed_req,other_br,'QA fence customer',phone,'EG',car,consent);exception when insufficient_privilege then denied:=true;end;assert denied,'Closed nonce reused in another branch';
 perform set_config('request.jwt.claim.sub',other_actor::text,true);
 denied:=false;begin perform public.get_offline_customer_registration(closed_req);exception when insufficient_privilege then denied:=true;end;assert denied,'Other actor recovered tombstone';
 denied:=false;begin perform public.close_offline_customer_registration(closed_req,br);exception when insufficient_privilege then denied:=true;end;assert denied,'Other actor closed existing nonce';
 denied:=false;begin perform public.register_offline_customer(closed_req,br,'QA fence customer',phone,'EG',car,consent);exception when insufficient_privilege then denied:=true;end;assert denied,'Other actor reused closed nonce';
 execute 'reset role';
 assert (select count(*) from private.offline_customer_profiles)=profile_count,'Close created a profile';
 assert (select count(*) from private.offline_customer_enrollment_receipts)=receipt_count,'Close issued a secret';
 assert not exists(select 1 from private.offline_customer_registration_requests where request_id=closed_req);
 assert (select count(*) from public.business_audit_log where action='offline_registration_closed' and entity_id=closed_req::text)=1,'Close replay appended duplicate audit';
 denied:=false;begin update private.offline_registration_closed_requests set branch_id=other_br where request_id=closed_req;exception when raise_exception then denied:=true;end;assert denied,'Tombstone was mutable';
 execute 'set local role authenticated';perform set_config('request.jwt.claim.sub',own::text,true);
 created:=public.register_offline_customer(created_req,br,'QA fence customer',phone,'EG',car,consent);
 assert created->>'status'='created_unverified' and length(created->>'enrollment_secret')=64;
 r:=public.close_offline_customer_registration(created_req,br);
 assert r->>'state'='succeeded' and r->'result'=(created||jsonb_build_object('enrollment_secret',null)),'Close must return original stored receipt when creation won';
 again:=public.close_offline_customer_registration(created_req,br);assert again=r;
 again:=public.get_offline_customer_registration(created_req);assert again=r->'result' and again->'enrollment_secret'='null'::jsonb;
 again:=public.register_offline_customer(created_req,br,'QA fence customer',phone,'EG',car,consent);assert again=r->'result','Exact retry after close must not reissue secret';
 perform set_config('request.jwt.claim.sub',other_actor::text,true);
 denied:=false;begin perform public.close_offline_customer_registration(created_req,br);exception when insufficient_privilege then denied:=true;end;assert denied,'Other actor recovered created receipt through close';
 perform set_config('request.jwt.claim.sub',own::text,true);
 denied:=false;begin perform public.close_offline_customer_registration(created_req,other_br);exception when insufficient_privilege then denied:=true;end;assert denied;
 execute 'reset role';
 assert not exists(select 1 from private.offline_registration_closed_requests where request_id=created_req),'Creation winner was falsely tombstoned';
 assert (select count(*) from private.offline_customer_profiles)=profile_count+1;
 assert (select count(*) from private.offline_customer_enrollment_receipts)=receipt_count+1;
 assert not exists(select 1 from public.business_audit_log where action='offline_registration_closed' and entity_id=created_req::text);
 raise notice 'PASS close-first permanent fence, actor/branch isolation, immutable/idempotent tombstone, creation-first actual receipt, no cancellation or repeated secret';
end $$;
rollback;
